function MiniBarChart() {
  return (
    <div className="flex items-end gap-1.5" aria-hidden>
      <span className="h-8 w-2 rounded-[10px] bg-[#6777B2]" />
      <span className="h-5 w-2 rounded-[10px] bg-[#778CCB]" />
      <span className="h-8 w-2 rounded-[10px] bg-[#97ABDE]" />
    </div>
  );
}

