function StatIcon({ type }) {
  const cls = "h-4 w-4 shrink-0 text-[#293B93]";

  if (type === "volume") {
    return (
      <svg className={cls} viewBox="0 0 24 24" fill="none" aria-hidden>
        <circle cx="12" cy="12" r="8.5" stroke="currentColor" strokeWidth="1.6" />
        <path d="M12 7V12H16" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
      </svg>
    );
  }

  if (type === "clock") {
    return <FooterMetaIcon type="clock" />;
  }

  return <FooterMetaIcon type="globe" />;
}

function TrendingCard({ item, t, index, isMobile }) {
  const footerIcon = item.footerIcon ?? "volume";
  const footerText = t(`items.${index}.footerText`, item.footerText ?? item.footer?.text ?? `Volume: ${item.volume ?? "1.2M"}`);

  return (
    <article className="flex h-full flex-col p-6"
      style={{
        borderRadius: "50px 25px",
        background: "#FFF",
        boxShadow: isMobile ? "none" : "0 4px 50px 0 rgba(41, 59, 147, 0.15)",
      }}
    >
      <span style={{
        borderRadius: "12px 5px",
        background: "#EEF0F6",
      }} className="p-2 w-fit">
        <AssetIcon />
      </span>

      <div className="mt-4 text-left">
        <p className="HeadingH5 font-semibold text-[#000032]">{t(`items.${index}.name`, item.name)}</p>
        <span className="TextSmall mt-2 inline-flex rounded-full bg-[#EEF0F6] px-2.5 py-1 font-normal text-[#9AA3C6]">
          {t(`items.${index}.code`, item.code ?? item.symbol)}
        </span>
      </div>

      <div className="mt-10 border-t border-[#E1E7F6] pt-4 flex items-center justify-between gap-3">
        <p className="HeadingH5 font-semibold text-[#000032]">{item.price}</p>
        <span
          className={clsx(
            "rounded-full px-2.5 py-1 text-xs font-normal",
            item.positive ? "bg-[#EEF0F6] text-[#04C120]" : "bg-[#EEF0F6] text-[#CF4548]"
          )}
        >
          {item.change}
        </span>
      </div>

      <div className="mt-4">
        <MiniBarChart />
      </div>

      <div className="mt-auto flex items-center gap-2 pt-5">
        <FooterMetaIcon type={footerIcon} />
        <span className="TextSmall font-normal text-[#999]">{footerText}</span>
      </div>
    </article>
  );
}

export default function AssetTrendingSection({ data }) {
  const { trending } = data;
  const t = usePathTranslation(`${data.i18nKey}.trending`);
  const footerStats = trending.footerStats ?? [];

  return (
    <section className="relative overflow-hidden py-10 md:py-16">
      <div
        className="pointer-events-none absolute opacity-60 inset-0 -z-10"
        aria-hidden
        style={{
          backgroundImage: `url('${TRENDING_BACKGROUND_IMAGE}'), linear-gradient(180deg, #E9EDF5 0%, #FFFFFF 100%)`,
          backgroundSize: "contain",
        }}
      />
      <div
        className="pointer-events-none absolute -right-24 top-0 -z-10 h-80 w-80 rounded-full blur-3xl"
        aria-hidden
        style={{ background: "rgba(41, 59, 147, 0.29)" }}
      />

      <div className="container min-w-0 max-w-full">
        <div className="mx-auto max-w-6xl text-center">
          <FadeInSection>
            <span className="inline-flex items-center gap-2 rounded-full bg-[#DCE2F6] px-4 py-2">
              <span className="h-2 w-2 rounded-full bg-[#293B93]" aria-hidden />
              <span className="TextSmall font-normal text-[#293B93]">{t("badge", trending.badge ?? "Hot topic")}</span>
            </span>
          </FadeInSection>
          <FadeInSection delay={0.1}>
            <h2 className="HeadingH1 mx-auto mt-5 font-semibold text-[#000]">{t("title", trending.title)}</h2>
            <p className="Text mx-auto mt-4 max-w-3xl font-normal leading-[1.7] text-[#4E4E4E]">{t("sub", trending.sub)}</p>
          </FadeInSection>

          {/* Mobile carousel */}
          <div className="md:hidden mt-12">
            <MobilePeekCarousel
              items={trending.items}
              renderItem={(item, index) => (
                <div className="px-1 pb-2" key={index}>
                  <TrendingCard item={item} t={t} index={index} isMobile={true} />
                </div>
              )}
            />
          </div>
          {/* Desktop grid */}
          <div className="hidden md:grid mt-12 gap-5 md:grid-cols-4">
            {trending.items.map((item, index) => (
              <div key={index}>
                <FadeInSection delay={index * 0.2}>
                  <TrendingCard item={item} t={t} index={index} isMobile={false} />
                </FadeInSection>
              </div>
            ))}
          </div>

          <div className="mt-10 flex flex-col items-center justify-between gap-6 border-t border-[#E8EDFA] pt-8 lg:flex-row">
            <div className="flex flex-col flex-wrap items-center justify-center gap-6 sm:flex-row lg:justify-start">
              {footerStats.map((stat, index) => (
                <div key={index}>
                  <FadeInSection delay={index * 0.2}>
                    <span className="inline-flex items-center gap-2">
                      <StatIcon type={stat.icon} />
                      <span className="TextSmall font-normal text-[#7D829A]">{t(`footerStats.${index}.text`, stat.text)}</span>
                    </span>

                  </FadeInSection>
                </div>
              ))}
            </div>

            <FadeInSection delay={0.2}>
              <Button
                href={REGISTER_HREF}
                external
                variant="brand"
                size="md"
                showArrow
              >
                {t("footerCta", trending.footerCta ?? "Start trading")}
              </Button>
            </FadeInSection>
          </div>
        </div>
      </div>
    </section>
  );
}
